#pragma once
#include "../source/playground/PlaygroundExperiment.h"
#include "../source/playground/PlaygroundController.h"
#include <QStandardPaths>

static void playgroundBackendRegressions() {
    auto config=Playground::example();config["competitions"]=24;config["athletes"]=12;config["focus"]=5;config["rounds"]=QJsonArray{12,6};config["sampleLimit"]=4;config["threads"]=1;config["variants"]=QJsonArray{QJsonObject{{"name","A"},{"changes",QJsonObject()}},QJsonObject{{"name","B"},{"changes",QJsonObject()}}};QString error;check(Playground::validate(config,error),"valid experiment config accepted");
    const auto before=GlobalSimulationSettings::snapshot();const auto one=Playground::run(config,std::make_shared<Playground::Control>());check(one["completed"].toInt()==24 && one["variants"].toArray().size()==2,"headless batch completes every paired competition");const auto variants=one["variants"].toArray();check(variants[0].toObject()["athletes"]==variants[1].toObject()["athletes"] && variants[1].toObject()["pairedPlace"].toObject()["mean"].toDouble()==0 && variants[1].toObject()["pairedPoints"].toObject()["mean"].toDouble()==0,"identical variants produce identical athlete distributions and zero paired effects");
    config["threads"]=4;const auto parallel=Playground::run(config,std::make_shared<Playground::Control>());check(parallel["threadsUsed"].toInt()==4 && parallel["completed"]==one["completed"],"batch uses requested worker pool");for(int i=0;i<2;++i){const auto a=variants[i].toObject(),b=parallel["variants"].toArray()[i].toObject();check(a["distance"].toObject()["histogram"]==b["distance"].toObject()["histogram"] && a["samples"]==b["samples"] && std::abs(a["distance"].toObject()["mean"].toDouble()-b["distance"].toObject()["mean"].toDouble())<1e-10,"thread count preserves distributions, samples and means");}
    const auto replay=Playground::replay(config,1,2);check(replay==Playground::replay(config,1,2) && replay["standings"].toArray().size()==12 && replay["jumps"].toArray().size()>=18,"competition replay is deterministic and includes every athlete and jump");const auto sample=parallel["variants"].toArray()[1].toObject()["samples"].toArray()[2].toObject();check(replay["gate"]==sample["gate"] && replay["standings"].toArray()[5].toObject()["place"]==sample["place"],"replayed competition matches retained focus sample");
    auto changed=config;changed["variants"]=QJsonArray{QJsonObject{{"name","A"},{"changes",QJsonObject()}},QJsonObject{{"name","B"},{"changes",QJsonObject{{"athlete.takeoff",20}}}}};const auto effect=Playground::run(changed,std::make_shared<Playground::Control>());check(effect["variants"].toArray()[1].toObject()["focusDistance"].toObject()["mean"].toDouble()<effect["variants"].toArray()[0].toObject()["focusDistance"].toObject()["mean"].toDouble(),"focused athlete skill changes reach actual jump engine");const auto after=GlobalSimulationSettings::snapshot();check(before.simulationRandomMultiplier==after.simulationRandomMultiplier && before.takeoffFormEffect==after.takeoffFormEffect && before.hillsEffectsMultiplier==after.hillsEffectsMultiplier && before.updateGlobalDatabaseRecords==after.updateGlobalDatabaseRecords,"experiments do not alter game engine settings or record policy");
    auto control=std::make_shared<Playground::Control>();control->canceled.store(true);const auto canceled=Playground::run(config,control);check(canceled["completed"].toInt()==0 && canceled["canceled"].toBool(),"canceled experiment returns an explicit empty partial report");
    QTemporaryDir directory;check(Playground::exportReport(parallel,directory.path(),error),"JSON and CSV experiment export succeeds");check(QFile::exists(directory.filePath("athletes.csv")) && QFile::exists(directory.filePath("focus-samples.csv")) && !Playground::exportReport(parallel,directory.path(),error),"export includes micro and macro CSV and never overwrites a prior report");QFile json(directory.filePath("report.json"));check(json.open(QIODevice::ReadOnly) && QJsonDocument::fromJson(json.readAll()).object()==parallel,"report JSON round trip preserves all statistics");
    auto invalid=config;invalid["competitions"]=0;check(!Playground::validate(invalid,error),"empty experiment rejected");invalid=config;invalid["parameters"]=QJsonObject{{"wind.deviation",-1}};check(!Playground::validate(invalid,error),"invalid parameter rejected before worker execution");invalid=config;invalid["roster"]=QJsonArray{QJsonObject()};check(!Playground::validate(invalid,error),"malformed imported roster rejected");
    CompetitionRules rules;RoundInfo first(12,true);first.setKO(true);first.setCountInKOGroup(2);first.setAdvancingFromKOGroup(1);first.setKoGroupsSelectionType(CompetitionRules::Classic);rules.setRounds({first,RoundInfo(7,true)});rules.setHasJudgesPoints(true);rules.setHasWindCompensations(true);auto knockout=config;knockout["rulesData"]=CompetitionRules::getJsonObject(rules);knockout["competitions"]=3;const auto ko=Playground::run(knockout,std::make_shared<Playground::Control>());check(ko["completed"].toInt()==3 && ko["variants"].toArray()[0].toObject()["jumps"].toInt()>=57,"headless experiments use real KO winners and lucky-loser advancement");
    auto team=config;team["athletes"]=40;team["focus"]=0;team["competitions"]=2;team["rounds"]=QJsonArray{40,20};rules.setCompetitionType(CompetitionRules::Team);rules.setJumpersInTeamCount(4);rules.setRounds({RoundInfo(10,true),RoundInfo(5,true)});team["rulesData"]=CompetitionRules::getJsonObject(rules);const auto teams=Playground::run(team,std::make_shared<Playground::Control>());check(teams["completed"].toInt()==2 && teams["variants"].toArray()[0].toObject()["jumps"].toInt()>=120 && Playground::replay(team,0,0)["team"].toBool(),"headless team contests simulate squads and advance through real team rules");
    qInfo()<<"PASS: playground headless competitions, repeatability, multiple threads, parameter effects, isolation, cancellation, exports, KO and teams";
}

static void playgroundUiRegressions(MainWindow &main) {
    QStandardPaths::setTestModeEnabled(true);main.show();main.resize(1280,900);PlaygroundWindow window(&main);render(&window,"playground-setup",true);auto *controller=window.findChild<PlaygroundController *>();check(controller && item(scene(&window)->rootObject(),"playgroundScreen"),"dedicated playground workspace opens");auto config=Playground::example();config["competitions"]=12;config["threads"]=3;config["athletes"]=12;config["focus"]=5;config["rounds"]=QJsonArray{12,6};config["sampleLimit"]=3;check(controller->configure(config.toVariantMap()),"UI accepts controlled experiment fixture");clickControl(scene(&window),"playgroundRun");check(controller->busy() || controller->report().value("completed").toInt()==12,"real run button starts background computation");QElapsedTimer wait;wait.start();while(controller->busy() && wait.elapsed()<15000)QTest::qWait(20);check(!controller->busy() && controller->report().value("completed").toInt()==12,"UI background experiment completes without blocking");render(&window,"playground-comparison",true);auto *root=item(scene(&window)->rootObject(),"playgroundScreen");root->setProperty("section",2);QTest::qWait(100);render(&window,"playground-athlete",true);root->setProperty("section",3);QTest::qWait(100);clickControl(scene(&window),"playgroundReplay");wait.restart();while(controller->busy() && wait.elapsed()<15000)QTest::qWait(20);check(!controller->busy() && controller->replayResult().value("standings").toList().size()==12,"real replay action shows full competition standings");render(&window,"playground-replay",true);root->setProperty("section",4);QTest::qWait(80);check(!controller->history().isEmpty(),"completed experiments are retained in history");root->setProperty("section",5);QTest::qWait(80);render(&window,"playground-cli");window.reject();qInfo()<<"PASS: playground setup, real run/replay, charts, athlete perspective, history, CLI guidance and responsive themes";
}
